DO $$
DECLARE v_all int; v_active int; v_progress int; v_orphans int;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE is_published) INTO v_all, v_active
  FROM public.learning_items WHERE item_type='vocabulary';
  SELECT count(*) INTO v_progress FROM public.review_progress;
  SELECT count(*) INTO v_orphans FROM public.review_progress rp LEFT JOIN public.learning_items li ON li.id=rp.item_id WHERE li.id IS NULL;
