  )
  SELECT count(*) INTO v_mismatch
  FROM expected e
  LEFT JOIN public.learning_items li ON li.id = e.id::uuid
  WHERE li.id IS NULL OR li.item_type IS DISTINCT FROM 'vocabulary'
     OR li.prompt IS DISTINCT FROM e.prompt OR li.reading IS DISTINCT FROM e.reading
     OR li.meaning_id IS DISTINCT FROM e.meaning_id OR li.jlpt_level IS DISTINCT FROM e.jlpt_level
     OR li.is_published IS DISTINCT FROM e.is_published
     OR (li.extra->>'chapter_number')::int IS DISTINCT FROM e.chapter_number
     OR li.extra->>'chapter_title' IS DISTINCT FROM e.chapter_title
     OR (li.extra->>'sort_order')::int IS DISTINCT FROM e.sort_order
     OR li.extra->>'romaji' IS DISTINCT FROM e.romaji
     OR li.extra->>'jenis' IS DISTINCT FROM e.jenis
     OR li.extra->>'category' IS DISTINCT FROM e.category
     OR li.extra->>'curriculum' IS DISTINCT FROM e.curriculum
     OR li.extra->>'dataset' IS DISTINCT FROM e.dataset;
  IF v_mismatch <> 0 THEN RAISE EXCEPTION 'R1 affected-row baseline mismatch count=%', v_mismatch; END IF;
END $$;

-- 3) All deprecation candidates must still have zero review_progress references.
DO $$
DECLARE v_refs int;
BEGIN
  SELECT count(*) INTO v_refs FROM public.review_progress WHERE item_id IN ('8880d3a1-88e1-4497-a7e7-948adaca5bfc'::uuid, 'bc1ef036-8dec-49ce-8ca6-5df3dca7086c'::uuid, 'b0460c1a-8953-443a-9c8a-a88892bc02df'::uuid, '6a7d73d6-97cf-4326-8123-19a666660ba2'::uuid, '0fbf99e2-bf19-4406-bd94-82f9196b0139'::uuid, 'f24d19ad-a9f1-46d3-80b7-c15a92c79af8'::uuid, 'a0d6fa6b-b6c1-43c4-9a51-de040d6a93e5'::uuid, 'f3ff9b1c-8c5e-465a-9f74-a9495d64a6b9'::uuid, '873fcca7-b921-4100-91aa-6f3565cbcff8'::uuid, '75863a62-3f7a-4402-b187-142a00f5a1f3'::uuid, 'c52b3a48-cac8-4957-afe4-10d702f39b32'::uuid);
