-- 5) Controlled duplicate delete: exact UUID only, before correcting Bab 1 電話番号.
DO $$
DECLARE v_rows int;
BEGIN
  DELETE FROM public.learning_items
  WHERE id='0fbf99e2-bf19-4406-bd94-82f9196b0139'::uuid AND item_type='vocabulary'
    AND prompt='電話番号' AND reading='でんわばんごう'
    AND (extra->>'chapter_number')::int=7 AND is_published=true;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN RAISE EXCEPTION 'R1 duplicate phone delete affected % rows', v_rows; END IF;
END $$;

