UPDATE public.learning_items li SET
  prompt=c.prompt,
  reading=c.reading,
  extra=jsonb_set(
    jsonb_set(
      jsonb_set(
        jsonb_set(
          jsonb_set(li.extra,'{romaji}',to_jsonb(c.romaji::text),true),
          '{jenis}',to_jsonb(c.jenis::text),true),
        '{category}',to_jsonb(c.category::text),true),
      '{chapter_number}',to_jsonb(c.chapter_number::int),true),
    '{chapter_title}',to_jsonb(c.chapter_title::text),true)
FROM changes c WHERE li.id=c.id::uuid AND li.item_type='vocabulary';

-- 7) Soft deprecate exactly 10 rows; preserve UUID/history and review_progress relationship.
DO $$
DECLARE v_rows int;
BEGIN
  UPDATE public.learning_items SET is_published=false
  WHERE item_type='vocabulary' AND is_published=true AND id IN ('6a7d73d6-97cf-4326-8123-19a666660ba2'::uuid, '75863a62-3f7a-4402-b187-142a00f5a1f3'::uuid, '873fcca7-b921-4100-91aa-6f3565cbcff8'::uuid, '8880d3a1-88e1-4497-a7e7-948adaca5bfc'::uuid, 'a0d6fa6b-b6c1-43c4-9a51-de040d6a93e5'::uuid, 'b0460c1a-8953-443a-9c8a-a88892bc02df'::uuid, 'bc1ef036-8dec-49ce-8ca6-5df3dca7086c'::uuid, 'c52b3a48-cac8-4957-afe4-10d702f39b32'::uuid, 'f24d19ad-a9f1-46d3-80b7-c15a92c79af8'::uuid, 'f3ff9b1c-8c5e-465a-9f74-a9495d64a6b9'::uuid);
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 10 THEN RAISE EXCEPTION 'R1 soft deprecation affected % rows', v_rows; END IF;
END $$;

