  )
  SELECT count(*) INTO v_mismatch FROM expected e LEFT JOIN public.learning_items li ON li.id=e.id::uuid
  WHERE li.id IS NULL OR li.prompt IS DISTINCT FROM e.prompt OR li.reading IS DISTINCT FROM e.reading
     OR li.extra->>'romaji' IS DISTINCT FROM e.romaji OR li.extra->>'jenis' IS DISTINCT FROM e.jenis
     OR li.extra->>'category' IS DISTINCT FROM e.category
     OR (li.extra->>'chapter_number')::int IS DISTINCT FROM e.chapter_number
     OR li.extra->>'chapter_title' IS DISTINCT FROM e.chapter_title;
  IF v_mismatch <> 0 THEN RAISE EXCEPTION 'R1 postflight changed-row mismatch=%', v_mismatch; END IF;
END $$;

-- 10) Postflight state, chapter, sort, verb-form, collision and progress assertions.
DO $$
DECLARE v_all int; v_active int; v_progress int; v_orphans int; v_bad_chapters int; v_bad_sort int; v_bad_verbs int; v_dupes int; v_phone int; v_soft int;
BEGIN
  SELECT count(*),count(*) FILTER (WHERE is_published) INTO v_all,v_active FROM public.learning_items WHERE item_type='vocabulary';
  SELECT count(*) INTO v_progress FROM public.review_progress;
  SELECT count(*) INTO v_orphans FROM public.review_progress rp LEFT JOIN public.learning_items li ON li.id=rp.item_id WHERE li.id IS NULL;
  SELECT count(*) INTO v_bad_chapters FROM (
    WITH expected(chapter_number,n) AS (VALUES (1,80),(2,65),(3,67),(4,64),(5,60),(6,65),(7,64),(8,66),(9,56),(10,66),(11,68),(12,64),(13,62),(14,65),(15,57),(16,45),(17,53),(18,60),(19,60),(20,58),(21,56),(22,65),(23,57),(24,56),(25,58),(26,60),(27,53),(28,50),(29,54),(30,44),(31,55),(32,63),(33,54),(34,59),(35,60))
    SELECT e.chapter_number FROM expected e LEFT JOIN (
      SELECT (extra->>'chapter_number')::int chapter_number,count(*)::int n FROM public.learning_items
      WHERE item_type='vocabulary' AND is_published GROUP BY 1
    ) a USING(chapter_number) WHERE a.n IS DISTINCT FROM e.n
  ) q;
  SELECT count(*) INTO v_bad_sort FROM (
    SELECT (extra->>'chapter_number')::int ch FROM public.learning_items
    WHERE item_type='vocabulary' AND is_published GROUP BY 1
    HAVING min((extra->>'sort_order')::int)<>1 OR max((extra->>'sort_order')::int)<>count(*)
       OR count(distinct (extra->>'sort_order')::int)<>count(*)
  ) q;
  SELECT count(*) INTO v_bad_verbs FROM public.learning_items WHERE item_type='vocabulary' AND is_published
    AND (extra->>'chapter_number')::int BETWEEN 1 AND 17 AND extra->>'jenis'='KK' AND prompt NOT LIKE '%ます';
  SELECT count(*) INTO v_dupes FROM (
    SELECT prompt,coalesce(reading,''),count(*) FROM public.learning_items WHERE item_type='vocabulary' GROUP BY 1,2 HAVING count(*)>1
  ) q;
  SELECT count(*) INTO v_phone FROM public.learning_items WHERE item_type='vocabulary' AND id='b7acbaae-5605-4839-84e3-9293f707effd'::uuid
    AND prompt='電話番号' AND reading='でんわばんごう' AND (extra->>'chapter_number')::int=1;
  SELECT count(*) INTO v_soft FROM public.learning_items WHERE item_type='vocabulary' AND is_published=false
    AND id IN ('6a7d73d6-97cf-4326-8123-19a666660ba2'::uuid, '75863a62-3f7a-4402-b187-142a00f5a1f3'::uuid, '873fcca7-b921-4100-91aa-6f3565cbcff8'::uuid, '8880d3a1-88e1-4497-a7e7-948adaca5bfc'::uuid, 'a0d6fa6b-b6c1-43c4-9a51-de040d6a93e5'::uuid, 'b0460c1a-8953-443a-9c8a-a88892bc02df'::uuid, 'bc1ef036-8dec-49ce-8ca6-5df3dca7086c'::uuid, 'c52b3a48-cac8-4957-afe4-10d702f39b32'::uuid, 'f24d19ad-a9f1-46d3-80b7-c15a92c79af8'::uuid, 'f3ff9b1c-8c5e-465a-9f74-a9495d64a6b9'::uuid);
  IF v_all<>2099 OR v_active<>2089 OR v_progress<>142 OR v_orphans<>0 OR v_bad_chapters<>0 OR v_bad_sort<>0 OR v_bad_verbs<>0 OR v_dupes<>0 OR v_phone<>1 OR v_soft<>10 THEN
    RAISE EXCEPTION 'R1 postflight failed all=% active=% progress=% orphan=% chapter=% sort=% verbs=% dupes=% phone=% soft=%',
      v_all,v_active,v_progress,v_orphans,v_bad_chapters,v_bad_sort,v_bad_verbs,v_dupes,v_phone,v_soft;
  END IF;
END $$;

COMMIT;
